import{_ as a,o as t,c as i,a5 as s}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"IDA Pro 静态分析实操","description":"拿到一个没有源码的 .exe，你想知道它的校验逻辑藏在哪、正确密码是什么。IDA Pro 是把这段机器码还原成可读逻辑的行业标准工具。本文不讲 IDA 的全部功能，只讲完成一次静态分析必须会用的一组操作。","frontmatter":{"type":"howto","level":"basic"},"headers":[],"relativePath":"reverse-engineering/05-static-analysis/chapter-04-ida-pro.md","filePath":"reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"}'),r={name:"reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"};function n(d,e,c,l,o,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="ida-pro-静态分析实操" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">IDA Pro 静态分析实操 <a class="header-anchor" href="#ida-pro-静态分析实操" aria-label="Permalink to &quot;IDA Pro 静态分析实操&quot;">​</a></h1><blockquote data-src-line="4" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><p data-src-line="4" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">拿到一个没有源码的 <code>.exe</code>，你想知道它的校验逻辑藏在哪、正确密码是什么。IDA Pro 是把这段机器码还原成可读逻辑的行业标准工具。本文不讲 IDA 的全部功能，只讲完成一次静态分析必须会用的一组操作。</p></blockquote><p data-src-line="6" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><strong>前置条件</strong>：已读 <a href="./../04-pe-format/chapter-01-pe-headers.html">PE 文件格式</a>、<a href="./../02-assembly/chapter-02-x64-assembly.html">x64 汇编</a> 和<a href="./chapter-01-basics.html">静态分析基础</a>，电脑上安装了 IDA Pro（8.x 或 9.x，本文操作在两个大版本间通用）。分析一个你自己编写、有权分析的 Windows 程序练手效果最好。</p><h2 id="_1-加载文件" tabindex="-1" data-src-line="8" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">1. 加载文件 <a class="header-anchor" href="#_1-加载文件" aria-label="Permalink to &quot;1. 加载文件&quot;">​</a></h2><p data-src-line="10" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">启动 IDA，选择「New」（新建分析）并选中你的 <code>.exe</code>。IDA 会弹出加载对话框，其中两个选项需要注意：</p><ul data-src-line="12" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><li data-src-line="12" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><strong>Processor type</strong>：保持自动识别（x64 程序会识别为 <code>metapc</code> 64 位）。</li><li data-src-line="13" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><strong>Load resources / 其他加载选项</strong>：入门保持默认即可。</li></ul><p data-src-line="15" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">点 OK 后，IDA 自动反汇编并做一轮分析，几秒到几十秒后进入主界面。<strong>如果 IDA 报「架构识别错误」或加载成 32 位，多半是这个文件本身是 32 位或已被损坏</strong>——先用 Detect It Easy 确认架构（<a href="./chapter-01-basics.html">静态分析基础</a>第 2 节）。</p><p data-src-line="17" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">分析完成后，先把数据库存下来：<code>File → Save</code>。IDA 会把分析结果存进一个 <code>.i64</code>（64 位）或 <code>.idb</code>（32 位）数据库文件，下次直接打开数据库即可，无需重新分析。</p><h2 id="_2-认识主界面" tabindex="-1" data-src-line="19" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">2. 认识主界面 <a class="header-anchor" href="#_2-认识主界面" aria-label="Permalink to &quot;2. 认识主界面&quot;">​</a></h2><p data-src-line="21" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">IDA 默认打开几个窗口，你只需要先认识其中四个：</p><table tabindex="0"><thead data-src-line="23" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><tr data-src-line="23" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><th style="text-align:left;">窗口</th><th style="text-align:left;">快捷键</th><th style="text-align:left;">作用</th></tr></thead><tbody data-src-line="25" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><tr data-src-line="25" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;"><strong>IDA View</strong>（反汇编视图）</td><td style="text-align:left;"><code>Esc</code> 返回</td><td style="text-align:left;">显示当前地址的反汇编，最核心的窗口</td></tr><tr data-src-line="26" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;"><strong>Functions</strong>（函数窗口）</td><td style="text-align:left;">无（可在 View 菜单打开）</td><td style="text-align:left;">列出所有已识别函数</td></tr><tr data-src-line="27" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;"><strong>Strings</strong>（字符串窗口）</td><td style="text-align:left;"><code>Shift+F12</code></td><td style="text-align:left;">列出程序里的字符串</td></tr><tr data-src-line="28" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;"><strong>Imports</strong>（导入表窗口）</td><td style="text-align:left;">无（View → Open subviews）</td><td style="text-align:left;">列出导入函数</td></tr></tbody></table><p data-src-line="30" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">在反汇编视图里，<code>Space</code> 键在<strong>图形视图</strong>和<strong>文本视图</strong>之间切换。图形视图把函数画成带箭头的控制流图，更适合看整体；文本视图是逐行的汇编列表，更适合精读。入门建议先在图形视图里看懂结构。</p><h2 id="_3-定位到-main" tabindex="-1" data-src-line="32" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">3. 定位到 main <a class="header-anchor" href="#_3-定位到-main" aria-label="Permalink to &quot;3. 定位到 main&quot;">​</a></h2><p data-src-line="34" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">加载后 IDA 通常停在入口点（entry point），那里是 CRT 初始化代码，不是你要分析的逻辑。找到 <code>main</code> 的常用办法：</p><ol data-src-line="36" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><li data-src-line="36" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">在 <strong>Functions 窗口</strong>里搜 <code>main</code>（有符号的程序直接有这个名字）。</li><li data-src-line="37" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">如果没有符号，跳到入口点（<code>G</code> 输入 <code>start</code> 或入口点地址），往下找被 <code>call</code> 且以 <code>RCX</code>（argc）<code>RDX</code>（argv）传参的函数。</li></ol><p data-src-line="39" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">找到 <code>main</code> 后，双击进入它，按 <code>Space</code> 切到图形视图，你会看到一个清晰的函数结构。<strong>如果图形视图里函数边界混乱、指令全是 <code>db</code>（数据字节），说明 IDA 没正确识别函数</strong>——把光标放在函数起点按 <code>P</code>（创建函数）即可修正。</p><h2 id="decompile-xref" tabindex="-1" data-src-line="41" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">4. 看懂逻辑：反编译 + 交叉引用 <a class="header-anchor" href="#decompile-xref" aria-label="Permalink to &quot;4. 看懂逻辑：反编译 + 交叉引用 {#decompile-xref}&quot;">​</a></h2><p data-src-line="43" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">这是静态分析的核心循环，重复四步：</p><p data-src-line="45" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><strong>第一步，读伪代码。</strong> 光标停在函数内，按 <code>F5</code>，IDA 会弹出 Hex-Rays 反编译窗口，把汇编还原成类 C 代码。立刻就能看懂 <code>if</code>、循环和函数调用。</p><p data-src-line="47" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><strong>第二步，看导入函数调用。</strong> 在伪代码或反汇编里，导入函数会直接显示名字（如 <code>CreateFileW</code>、<code>WriteFile</code>）。看到这些调用，你就能判断这段代码在做什么操作。</p><p data-src-line="49" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><strong>第三步，查交叉引用。</strong> 对任何感兴趣的对象——一个字符串、一个函数、一个数据——把光标放上去按 <code>X</code>，IDA 列出「谁引用了它」以及引用位置。这是反推「某个字符串在哪个判断逻辑里被使用」的关键操作。例如看到字符串 <code>&quot;Wrong password&quot;</code>，按 <code>X</code> 找到引用它的代码，往上读就是密码校验逻辑。</p><p data-src-line="51" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><strong>第四步，回到反汇编核对。</strong> 伪代码可能误判类型或漏掉细节，关键判断处按 <code>Tab</code> 或点回反汇编视图，看 <code>cmp + jcc</code> 确认逻辑真实成立。</p><p data-src-line="53" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">这四个步骤循环进行，直到你复述出程序的核心行为。下面是一个浓缩的例子。</p><h2 id="_5-一个完整示例-分析密码校验" tabindex="-1" data-src-line="55" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">5. 一个完整示例：分析密码校验 <a class="header-anchor" href="#_5-一个完整示例-分析密码校验" aria-label="Permalink to &quot;5. 一个完整示例：分析密码校验&quot;">​</a></h2><p data-src-line="57" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">假设你有一个自编的 <code>check.exe</code>，逻辑是「输入密码，正确则打印成功」。用 IDA 分析它的过程如下：</p><ol data-src-line="59" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><li data-src-line="59" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">加载后，<code>Shift+F12</code> 打开字符串窗口，看到两个关键字符串：<code>&quot;Correct!&quot;</code> 和 <code>&quot;Wrong password&quot;</code>。</li><li data-src-line="60" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">双击 <code>&quot;Wrong password&quot;</code>，跳到它所在的数据位置；光标放上去按 <code>X</code>，看到只有一处引用，双击跳到引用它的代码。</li><li data-src-line="61" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">该处代码是一段比较逻辑，<code>F5</code> 反编译后形如：</li></ol><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">strcmp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;secret123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    puts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Correct!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    puts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Wrong password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol start="4" data-src-line="71" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><li data-src-line="71" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">回到反汇编核对：<code>strcmp</code> 的参数、<code>cmp eax, 0</code> 后接 <code>jne</code> 的分支，与伪代码一致。</li></ol><p data-src-line="73" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">到这一步，你已经在<strong>不运行程序</strong>的情况下，还原出了校验逻辑和正确密码。这就是静态分析的一个完整闭环。</p><h2 id="_6-常用操作速查" tabindex="-1" data-src-line="75" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">6. 常用操作速查 <a class="header-anchor" href="#_6-常用操作速查" aria-label="Permalink to &quot;6. 常用操作速查&quot;">​</a></h2><p data-src-line="77" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">把这一篇用到、以及下一阶段会用到的高频操作集中列在这里：</p><table tabindex="0"><thead data-src-line="79" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><tr data-src-line="79" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><th style="text-align:left;">操作</th><th style="text-align:left;">快捷键 / 方式</th></tr></thead><tbody data-src-line="81" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><tr data-src-line="81" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">跳转到地址</td><td style="text-align:left;"><code>G</code></td></tr><tr data-src-line="82" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">重命名（函数/变量/数据）</td><td style="text-align:left;"><code>N</code></td></tr><tr data-src-line="83" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">查交叉引用</td><td style="text-align:left;"><code>X</code></td></tr><tr data-src-line="84" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">反编译为伪代码</td><td style="text-align:left;"><code>F5</code></td></tr><tr data-src-line="85" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">图形 / 文本视图切换</td><td style="text-align:left;"><code>Space</code></td></tr><tr data-src-line="86" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">字符串窗口</td><td style="text-align:left;"><code>Shift+F12</code></td></tr><tr data-src-line="87" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">加注释</td><td style="text-align:left;"><code>;</code>（普通注释）、<code>:</code>（可重复注释）</td></tr><tr data-src-line="88" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">修改变量/函数类型</td><td style="text-align:left;"><code>Y</code></td></tr><tr data-src-line="89" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">创建函数</td><td style="text-align:left;"><code>P</code></td></tr><tr data-src-line="90" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">撤销一次分析（把代码还原成数据）</td><td style="text-align:left;"><code>U</code></td></tr><tr data-src-line="91" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><td style="text-align:left;">保存数据库</td><td style="text-align:left;"><code>Ctrl+S</code></td></tr></tbody></table><p data-src-line="93" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">其中 <strong>重命名（<code>N</code>）</strong> 值得单独强调：反汇编出来的函数和变量都是无意义的名字（<code>sub_140001000</code>、<code>v1</code>）。每当你搞懂一个函数或变量在做什么，立刻按 <code>N</code> 给它起一个有意义的名字。这样随着分析推进，反汇编会越来越「自解释」，这是 IDA 工作流的核心习惯。</p><h2 id="_7-失败与回退" tabindex="-1" data-src-line="95" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">7. 失败与回退 <a class="header-anchor" href="#_7-失败与回退" aria-label="Permalink to &quot;7. 失败与回退&quot;">​</a></h2><ul data-src-line="97" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><li data-src-line="97" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><strong>IDA 识别不出函数</strong>：入口或某段代码显示成 <code>db</code> 数据 → 光标定位后按 <code>P</code> 创建函数；反之若一段数据被误当成代码，按 <code>U</code> 还原。</li><li data-src-line="98" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><strong>反编译结果明显不对</strong>（如大量 <code>unknown</code>、错误的循环）→ 通常是分析信息不足，先 <code>N</code> 重命名、<code>Y</code> 修正参数类型，再 <code>F5</code> 重试。</li><li data-src-line="99" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><strong>加载时架构选错</strong> → <code>File → New</code> 重新加载，注意 Processor type；或先确认文件位数。</li></ul><p data-src-line="101" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">IDA 的界面和快捷键在 8.x / 9.x 间保持稳定，本文操作在两个大版本都适用。</p><hr><blockquote data-src-line="105" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md"><p data-src-line="105" data-src-file="reverse-engineering/05-static-analysis/chapter-04-ida-pro.md">本章走通了 IDA 的一次完整静态分析：加载 → 定位 <code>main</code> → 反编译 + 交叉引用 → 还原逻辑。下一章用免费的 <a href="./chapter-05-ghidra.html">Ghidra</a> 完成同样的分析，并介绍它相对 IDA 的脚本化优势。</p></blockquote>`,38)])])}const y=a(r,[["render",n]]);export{h as __pageData,y as default};
